  "Matching data (gender, major, hometown) is used only for the Term you apply for. The dormitory office keeps Application records for the period required by FPT University regulations, then deletes them.": "Dữ liệu ghép phòng (giới tính, ngành, quê quán) chỉ dùng cho kỳ bạn đăng ký. Văn phòng ký túc xá lưu hồ sơ đơn trong thời gian theo quy định của Đại học FPT, sau đó xóa.",
  "You can ask the dormitory office to see, correct or withdraw consent for your data at any time, as set out in the Personal Data Protection Law 91/2025/QH15 and Decree 356/2025/NĐ-CP.": "Bạn có thể yêu cầu văn phòng ký túc xá cho xem, sửa hoặc rút lại sự đồng ý đối với dữ liệu của mình bất cứ lúc nào, theo Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 và Nghị định 356/2025/NĐ-CP.",
